using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{public void Execute(ExecutionResult result){var s=SceneManager.GetActiveScene();var r=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).First(r=>r.enabled&&r.name.Contains("island_tree_02"));for(var t=r.transform;t;t=t.parent)result.Log(t.name+" rot="+t.localEulerAngles+" scale="+t.localScale);result.Log("bounds="+r.bounds);var b=r.bounds;var go=new GameObject("__QA");var c=go.AddComponent<Camera>();c.fieldOfView=50;c.transform.position=b.center+new Vector3(b.size.y*.7f,0,-b.size.y*.8f);c.transform.LookAt(b.center);MMSequentialEvidence.Render(c,"Validation/VisualRefinement/tree_material_before.png",900,900);var old=r.sharedMaterials;var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Environment/FinalWorldVegetation/island_tree_02.prefab");r.sharedMaterials=p.GetComponentsInChildren<Renderer>(true).First(a=>a.enabled).sharedMaterials;MMSequentialEvidence.Render(c,"Validation/VisualRefinement/tree_material_preview.png",900,900);r.sharedMaterials=old;UnityEngine.Object.DestroyImmediate(go);result.Log("Preview restored; no save");}}
